import pyomo.environ as pyo

DATA = {
    "num_centers": 8,
    "num_stores": 9,
    "opening_cost": {
        1: 151000, 2: 192000, 3: 114000, 4: 171000,
        5: 160000, 6: 120000, 7: 182000, 8: 186000,
    },
    "transport_cost": {
        1: {1: 3, 2: 3, 3: 5, 4: 4, 5: 3, 6: 5, 7: 2, 8: 4, 9: 2},
        2: {1: 4, 2: 5, 3: 1, 4: 4, 5: 2, 6: 5, 7: 4, 8: 1, 9: 1},
        3: {1: 3, 2: 3, 3: 2, 4: 4, 5: 4, 6: 3, 7: 4, 8: 4, 9: 1},
        4: {1: 3, 2: 5, 3: 3, 4: 5, 5: 1, 6: 2, 7: 4, 8: 1, 9: 4},
        5: {1: 2, 2: 2, 3: 1, 4: 2, 5: 5, 6: 2, 7: 4, 8: 4, 9: 4},
        6: {1: 4, 2: 5, 3: 3, 4: 1, 5: 4, 6: 2, 7: 4, 8: 2, 9: 2},
        7: {1: 4, 2: 5, 3: 2, 4: 2, 5: 4, 6: 2, 7: 2, 8: 4, 9: 4},
        8: {1: 1, 2: 5, 3: 5, 4: 2, 5: 5, 6: 2, 7: 1, 8: 4, 9: 4},
    },
    "demand": {
        1: 779, 2: 892, 3: 440, 4: 556, 5: 414,
        6: 464, 7: 920, 8: 743, 9: 528,
    },
    "capacity": {
        1: 1447, 2: 1886, 3: 1962, 4: 1392,
        5: 1191, 6: 1218, 7: 1088, 8: 1178,
    },
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.I = pyo.Set(initialize=list(range(1, d["num_centers"] + 1)))
    model.J = pyo.Set(initialize=list(range(1, d["num_stores"] + 1)))

    model.open = pyo.Var(model.I, within=pyo.Binary)
    model.ship = pyo.Var(model.I, model.J, within=pyo.NonNegativeReals)

    def obj_rule(m):
        opening = sum(d["opening_cost"][i] * m.open[i] for i in m.I)
        transport = sum(
            d["transport_cost"][i][j] * m.ship[i, j]
            for i in m.I for j in m.J
        )
        return opening + transport

    model.obj = pyo.Objective(expr=obj_rule, sense=pyo.minimize)

    def demand_rule(m, j):
        return sum(m.ship[i, j] for i in m.I) == d["demand"][j]

    model.demand_sat = pyo.Constraint(model.J, rule=demand_rule)

    def capacity_rule(m, i):
        return sum(m.ship[i, j] for j in m.J) <= d["capacity"][i] * m.open[i]

    model.capacity_link = pyo.Constraint(model.I, rule=capacity_rule)

    return model
